function openBusinessEditor(id=null){if(!canPost())return;const b=id?bizById(id):state.myBiz;if(b&&b.mine!==true&&b!==state.myBiz)return;editor={kind:'biz',id:b?.id||null,photos:[...(b?.photos||[])]};editorDirty=false;showDialog(b?.live?'Editar página':'Criar página do negócio',`<div class="form-grid">${field('biz-name','Nome do negócio',b?.name||'','required minlength="3" maxlength="100" class="full"')}${selectField('biz-category','Categoria',[['','Escolher categoria'],...CAT_NAMES.slice(1)],b?.cat||'','required')}${field('biz-hours','Horário ou agendamento',b?.hours||'','required maxlength="100"')}${field('biz-hoods','Bairros em que atende',(b?.hoods||[]).join(', '),'required supporting-text="Separe os bairros por vírgula." class="full"')}${field('biz-services','Serviços',(b?.svc||[]).join('\n'),'type="textarea" rows="3" required supporting-text="Um serviço por linha." class="full"')}${field('biz-bio','Apresentação',b?.bio||'','type="textarea" rows="3" maxlength="1500" class="full"')}${field('biz-discount','Benefício para a comunidade (opcional)',b?.disc||'','maxlength="120" class="full"')}${field('biz-whatsapp','WhatsApp (opcional)',b?.whatsapp||'','type="tel" inputmode="tel" supporting-text="DDD e número."')}${field('biz-instagram','Instagram (opcional)',b?.instagram||'','supporting-text="Nome do perfil, sem @."')}${field('biz-website','Site (opcional)',b?.website||'','type="url" class="full"')}${photoUploadHtml()}</div>`,`${btn('Cancelar','close-dialog','','text')}${btn(b?.live?'Salvar alterações':'Criar minha página','submit-biz','','filled')}`,'editor');}
async function submitBusiness(){if(!editor||!canPost()||!validFields(['biz-name','biz-category','biz-hours','biz-hoods','biz-services','biz-website']))return;const website=$('#biz-website').value.trim(),phone=$('#biz-whatsapp').value.replace(/\D/g,''),insta=$('#biz-instagram').value.trim().replace(/^@/,'');if(phone&&!/^\d{10,15}$/.test(phone)){notify('Confira o DDD e o número do WhatsApp.','error');return;}if(insta&&!/^[a-zA-Z0-9._]{1,30}$/.test(insta)){notify('Informe o nome válido do perfil do Instagram.','error');return;}if(website&&!/^https?:\/\//i.test(website)){notify('O site deve começar com https:// ou http://.','error');return;}const data={name:$('#biz-name').value.trim(),cat:$('#biz-category').value,hours:$('#biz-hours').value.trim(),hoods:$('#biz-hoods').value.split(',').map(x=>x.trim()).filter(Boolean),svc:$('#biz-services').value.split('\n').map(x=>x.trim()).filter(Boolean),bio:$('#biz-bio').value.trim(),disc:$('#biz-discount').value.trim(),whatsapp:phone,instagram:insta,website,photos:[...editor.photos]};if(!data.cat||!data.hoods.length||!data.svc.length){notify('Complete categoria, bairros e serviços.','error');return;}const id=editor.id||uid('b'),old=state.myBiz?.id===id?state.myBiz:null;const ok=mutate(()=>{state.myBiz={...(old||{id,recN:0,says:[],views:0,icon:'storefront',saved:false}),...data,mine:true,live:true,claimed:true,city:state.homeCity,ini:initals(data.name),owner:`${state.profile.name}, perfil de teste verificado`,demo:data.photos.some(p=>!p.startsWith('data:'))};},{redraw:false});if(ok){await closeDialog(true);navigate('negocio',id);notify(old?'Página atualizada':'Página criada');}}
